"""Original camera-guided nut controller. Uses only Robot public observations.
Run a single recorded stage: python gen.py approach|descend|grasp|lift|observe
No reset is used. All commands and observations are stored under /app/runs.
"""
import sys,json,time
from pathlib import Path
sys.path.insert(0,'/opt/tools')
import numpy as np
from rcb_client import Robot
OUT=Path('/app/runs'); OUT.mkdir(exist_ok=True)
r=Robot(); CAMS=list(r.spec()['cameras']); DT=r.spec()['control_dt']
def state(obs):
    p=obs.meta['proprio'];return dict(zip(p['layout'],p['now']))
def report(obs):
    s=state(obs)
    print(json.dumps({'tcp':[s['tcp_'+a] for a in 'xyz'], 'mocap':[s['mocap_'+a] for a in 'xyz'], 'opening':s['gripper_opening'],'target':obs.meta['task']['target_pos'],'steps':obs.meta['control_steps'],'time_left':obs.meta['time_left_s']}))
def save(obs,label,actions=None):
    path=OUT/label;obs.save(str(path))
    if actions is not None:np.save(path/'actions.npy',actions)
    report(obs)
    return obs
def observe(label='observe'):
    return save(r.get_obs(cameras=CAMS,include_depth=True),label)
def execute(actions,label):
    a=np.asarray(actions,np.float64)
    return save(r.submit('ee_delta',a,dt=DT,cameras=CAMS,include_depth=True,video='both',note=label),label,a)
def move_mocap(goal,grip,label,speed=.003,settle=40):
    o=r.get_obs(cameras=[],include_depth=False);s=state(o)
    delta=np.asarray(goal)-np.array([s['mocap_'+a] for a in 'xyz'])
    n=max(1,int(np.ceil(np.max(np.abs(delta))/speed)))
    a=np.zeros((n+settle,4));a[:n,:3]=delta/n/.01;a[:,3]=grip
    return execute(a,label)
def move_tcp(goal,grip,label,speed=.002,settle=40):
    o=r.get_obs(cameras=[],include_depth=False);s=state(o)
    tcp=np.array([s['tcp_'+a] for a in 'xyz']);mocap=np.array([s['mocap_'+a] for a in 'xyz'])
    return move_mocap(np.asarray(goal)+(mocap-tcp),grip,label,speed,settle)
if __name__=='__main__':
    stage=sys.argv[1] if len(sys.argv)>1 else 'observe'
    if stage=='approach':move_mocap([.183,.605,.225],-1,'01_approach')
    elif stage=='descend':move_tcp([.183,.605,.031],-1,'02_descend',speed=.0015)
    elif stage=='grasp':execute(np.tile([0,0,0,1.],(80,1)),'03_grasp')
    elif stage=='lift':move_tcp([.183,.605,.18],1,'04_lift',speed=.001)
    elif stage=='observe':observe('observe_'+str(int(time.time())))
    else:raise ValueError(stage)
